   304  static void latm_dmx_check_pid(GF_Filter *filter, GF_LATMDmxCtx *ctx)
   305  {
   306          u8 *dsi_b;
   307          u32 dsi_s, sr, timescale=0;
   308          u32 codecid;
   309          if (!ctx->opid) {
   310                  ctx->opid = gf_filter_pid_new(filter);
   311                  gf_filter_pid_copy_properties(ctx->opid, ctx->ipid);
   312                  latm_dmx_check_dur(filter, ctx);
   313          }
   314          if (!GF_M4ASampleRates[ctx->acfg.base_sr_index]) {
   315                  GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[LATMDmx] Wrong sample rate in audio config, broken stream\n"));
   316                  ctx->in_error = GF_NON_COMPLIANT_BITSTREAM;
   317                  return;
   318          }
   319
   320          if ((ctx->sr_idx == ctx->acfg.base_sr_index) && (ctx->nb_ch == ctx->acfg.nb_chan )
   321                  && (ctx->base_object_type == ctx->acfg.base_object_type) ) return;
   322
   323          if (ctx->acfg.base_object_type==GF_M4A_USAC)
   324                  codecid = GF_CODECID_USAC;
   325          else
   326                  codecid = GF_CODECID_AAC_MPEG4;
   327          //copy properties at init or reconfig
   328          gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_STREAM_TYPE, & PROP_UINT( GF_STREAM_AUDIO));
   329          gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_CODECID, & PROP_UINT( codecid));
   330          gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_SAMPLES_PER_FRAME, & PROP_UINT(ctx->frame_size) );
   331          gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_UNFRAMED, & PROP_BOOL(GF_FALSE) );
   332          if (ctx->is_file && ctx->index) {
   333                  gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_PLAYBACK_MODE, & PROP_UINT(GF_PLAYBACK_MODE_FASTFORWARD) );
   334          }
   335          if (ctx->duration.num)
   336                  gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_DURATION, & PROP_FRAC64(ctx->duration));
   337
   338
   339          ctx->nb_ch = ctx->acfg.nb_chan;
   340          ctx->base_object_type = ctx->acfg.base_object_type;
   341
   342          sr = GF_M4ASampleRates[ctx->acfg.base_sr_index];
   343          if (!ctx->timescale) {
   344                  //we change sample rate, change cts
   345                  if (ctx->cts && (ctx->sr_idx != ctx->acfg.base_sr_index)) {
   346                          ctx->cts *= sr;
   347                          ctx->cts /= GF_M4ASampleRates[ctx->sr_idx];
   348                  }
   349          }
   350          ctx->sr_idx = ctx->acfg.base_sr_index;
   351
   352          ctx->dts_inc = ctx->frame_size;
   353          gf_m4a_write_config(&ctx->acfg, &dsi_b, &dsi_s);
   354          gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_DECODER_CONFIG, & PROP_DATA_NO_COPY(dsi_b, dsi_s) );
   355          gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_PROFILE_LEVEL, & PROP_UINT (ctx->acfg.audioPL) );
   356          gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_SAMPLE_RATE, & PROP_UINT(sr));
   357
   358          timescale = sr;
   359
   360          gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_TIMESCALE, & PROP_UINT(ctx->timescale ? ctx->timescale : timescale));

